// texts returns the messages without arguments in lang, nil for a
// language the catalog lacks.
func texts(lang string) *i18n.Texts {
	switch lang {
	case "en":
		return textsEn
	case "zh-Hans":
		return textsZhHans
	}
	return nil
}

// suppliedTexts are the messages without arguments other packages
// supply, by language and index.
var suppliedTexts = map[string]*[numTexts]string{}

// text says the message without arguments at i in the language of msgs,
// else of the languages it falls back to, else of the source.
func (msgs Messages) text(i int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, textsEn.At(i))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if t := suppliedTexts[lang]; t != nil && t[i] != "" {
			return t[i]
		}
		if lang == "" {
			return textsEn.At(i)
		}
		if t := texts(lang); t != nil {
			if s := t.At(i); s != "" {
				return s
			}
		}
	}
}

// Supply adds the messages t has in lang to the catalog, over its own.
// nsgo writes the calls, in the package that supplies them, which runs
// them as it initializes.
func Supply(lang string, t Translation) {
	if len(t.Texts) > 0 {
		st := suppliedTexts[lang]
		if st == nil {
			st = new([numTexts]string)
			suppliedTexts[lang] = st
		}
		for i, key := range keyOfText {
			if s, ok := t.Texts[key]; ok {
				st[i] = s
			}
		}
	}
	s := supplied[lang]
	if t.OnlineCount != nil {
		s.OnlineCount = t.OnlineCount
	}
	if t.SendTo != nil {
		s.SendTo = t.SendTo
	}
	if t.FilesSelected != nil {
		s.FilesSelected = t.FilesSelected
	}
	if t.RemoveFile != nil {
		s.RemoveFile = t.RemoveFile
	}
	if t.IncomingFrom != nil {
		s.IncomingFrom = t.IncomingFrom
	}
	if t.IncomingDetail != nil {
		s.IncomingDetail = t.IncomingDetail
	}
	if t.PinDescription != nil {
		s.PinDescription = t.PinDescription
	}
	if t.Waiting != nil {
		s.Waiting = t.Waiting
	}
	if t.TransferSent != nil {
		s.TransferSent = t.TransferSent
	}
	if t.TransferReceived != nil {
		s.TransferReceived = t.TransferReceived
	}
	if t.TransferError != nil {
		s.TransferError = t.TransferError
	}
	if t.ServerRunning != nil {
		s.ServerRunning = t.ServerRunning
	}
	if t.SavedTo != nil {
		s.SavedTo = t.SavedTo
	}
	supplied[lang] = s
	Catalog.Add(lang)
}

// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

