// OnlineCount says "{count, plural, =0 {No devices online} one {1 device online} other {# devices online}}"
// in the language the app shows under cx.
//
// How many nearby devices answered.
func OnlineCount(cx *core.Scope, count int) string { return For(cx).OnlineCount(count) }

// OnlineCount is the package's OnlineCount in the language of msgs.
func (msgs Messages) OnlineCount(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.OnlineCount(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].OnlineCount; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch {
			case count == 0:
				b.WriteString("No devices online")
			default:
				switch i18n.Cardinal("en", float64(count)) {
				case i18n.One:
					b.WriteString("1 device online")
				default:
					b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
					b.WriteString(" devices online")
				}
			}
			return b.String()
		case "zh-Hans":
			var b strings.Builder
			switch {
			case count == 0:
				b.WriteString("没有设备在线")
			default:
				switch i18n.Cardinal("zh-Hans", float64(count)) {
				default:
					b.WriteString(i18n.FormatNumber("zh-Hans", float64(count)))
					b.WriteString(" 台设备在线")
				}
			}
			return b.String()
		}
	}
}

