// ServerRunning says "Receiving on {address}"
// in the language the app shows under cx.
func ServerRunning(cx *core.Scope, address string) string { return For(cx).ServerRunning(address) }

// ServerRunning is the package's ServerRunning in the language of msgs.
func (msgs Messages) ServerRunning(address string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.ServerRunning(address))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].ServerRunning; f != nil {
			return f(address)
		}
		switch lang {
		case "", "en":
			return "Receiving on " + msgs.arg(address)
		case "zh-Hans":
			return "正在 " + address + " 接收"
		}
	}
}

